def is_prime(m):
    if m < 2:
        return False
    d = 2
    while d * d <= m:
        if m % d == 0:
            return False
        d += 1
    return True

count = sum(1 for n in range(1, 101) if not is_prime(n ** 4 + 4))
print(count)

