import math
sums = set()
N = 20000
for sign in (1, -1):
    def root(x):
        return sign * math.sqrt(max(0.0, 13 - x * x))
    def g(x):
        return x ** 3 + root(x) ** 3 - 35
    xs = [-math.sqrt(13) + 2 * math.sqrt(13) * i / N for i in range(N + 1)]
    for a, b in zip(xs, xs[1:]):
        if g(a) * g(b) < 0:
            lo, hi = a, b
            for _ in range(200):
                m = (lo + hi) / 2
                if g(lo) * g(m) <= 0:
                    hi = m
                else:
                    lo = m
            x = (lo + hi) / 2
            sums.add(round(x + root(x), 6))
print(round(sum(sums)))

